/// <summary>
/// Base class for PricingAttribute table <c>InventTableModule</c>
/// </summary>
internal abstract class UPSPricingAttributeInventTableModule extends UPSAbstractPricingAttribute implements UPSIPricingAttribute
{

}

Method.Source:
protected InventTableModule getTableRecord(Common _pricingObject)
{
    SalesLine                       salesLine;
    SalesQuotationLine              salesQoutationLine;
    InventTableModule               inventTableModule;

    Switch (_pricingObject.tableId)
    {

        case tableNum(SalesLine):
            salesLine = _pricingObject as SalesLine;
            if (salesLine)
            {
                inventTableModule = salesLine.inventTable().inventTableModuleSales();
            }
            break;

        case tableNum(SalesQuotationLine):
            salesQoutationLine = _pricingObject as SalesQuotationLine;
            if (salesQoutationLine)
            {
                inventTableModule = salesQoutationLine.inventTable().inventTableModuleSales();
            }
            break;
    }

    return inventTableModule;
}

protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbdsRoot;

    if (_qbdsMap && _qbdsMap.exists(tableStr(InventTableModule)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(InventTableModule));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(InventTableModule));

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(InventTableModule), qbdsRoot);
        }
    }

    return qbdsRoot;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}
